-- @set: request.jwt.claims={"sub":"1","role":"authenticated","aud":"authenticated","pad":""}
-- Control: naive policy, but owner_id is indexed so the stable expression becomes an index condition.
create index if not exists documents_owner_idx on app.documents(owner_id);
alter table app.documents enable row level security;
create policy p on app.documents for select to bench_user
  using (owner_id = (current_setting('request.jwt.claims', true)::jsonb ->> 'sub')::int);
